content = "import urllib.request\nimport json\nfrom datetime import date, timedelta\nfrom secrets_loader import get_secret\n\ndef fetch_daily_prices(ticker='SPY', days_back=280):\n    token = get_secret('orats-api-token')\n    end = date.today()\n    start = end - timedelta(days=days_back)\n    prices = []\n    current = start\n    while current <= end:\n        if current.weekday() < 5:\n            date_str = current.isoformat()\n            url = f'https://api.orats.io/datav2/hist/dailies?token={token}&ticker={ticker}&tradeDate={date_str}'\n            try:\n                with urllib.request.urlopen(url) as response:\n                    data = json.loads(response.read())\n                    if data.get('data'):\n                        clsPx = data['data'][0].get('clsPx')\n                        if clsPx:\n                            prices.append((date_str, clsPx))\n            except Exception:\n                pass\n        current += timedelta(days=1)\n    return prices\n"
with open('check_ma_trend.py', 'w') as f:
    f.write(content)
print("Chunk 1 written")
